window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5dda4457e5e710b4"]={"versions": [{"id": "FIG-5dda4457e5e710b4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung mathematischer Formeln (<code>MlFormula</code>) innerhalb des AUTOSAR-Metamodells (Generic Structure Template). Es spezifiziert die Struktur zur Einbettung, Formatierung und sprachspezifischen Auflösung von Formeldarstellungen in Dokumentationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>MlFormula</code> (spezialisiert <code>Paginateable</code>). Sie aggregiert per Komposition:</p>\n<ul class=\"fig-list\"><li><code>+formulaCaption</code> [0..1] auf <code>Caption</code> (spezialisiert <code>MultilanguageReferrable</code>)\n</li><li><code>+texMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+genericMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+verbatim</code> [0..1] auf <code>MultiLanguageVerbatim</code> (spezialisiert <code>Paginateable</code>, Attribute: <code>allowBreak: NameToken [0..1]</code>, <code>float: FloatEnum [0..1]</code>, <code>helpEntry: String [0..1]</code>, <code>pgwide: PgwideEnum [0..1]</code>)\n</li><li><code>+lGraphic</code> [0..*] auf <code>LGraphic</code> (spezialisiert <code>LanguageSpecific</code>)\n</li></ul>\n<p class=\"fig-p\">Die textuellen Formelcontainer verzweigen in sprachspezifische Ausprägungen:</p>\n<ul class=\"fig-list\"><li><code>MultiLanguagePlainText</code> aggregiert per Komposition über Rolle <code>+l10</code> [1..*] die Klasse <code>LPlainText</code> (spezialisiert <code>LanguageSpecific</code> und erbt von <code>MixedContentForPlainText</code>). <code>MixedContentForPlainText</code> (spezialisiert <code>WhitespaceControlled</code>) enthält das Attribut <code>+ contents: VerbatimString</code>.\n</li><li><code>MultiLanguageVerbatim</code> aggregiert per Komposition über Rolle <code>+l5</code> [1..*] die Klasse <code>LVerbatim</code> (spezialisiert <code>LanguageSpecific</code>, Stereotyp <code>«atpMixedString»</code>). <code>MixedContentForVerbatim</code> (spezialisiert <code>WhitespaceControlled</code>, Stereotyp <code>«atpMixedString»</code>) erbt von <code>LVerbatim</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Kompositionen definieren die hierarchische Schachtelung im AUTOSAR-XML-Dokumentenmodell (ARXML), wobei mehrsprachige Container (<code>MultiLanguage*</code>) zur Lokalisierung sprachspezifische Kindelemente bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen berücksichtigen, dass eine Formel über verschiedene mathematische Notationen (TeX via <code>texMath</code>, generische Textmathematik via <code>genericMath</code>, vorformatierter Text via <code>verbatim</code> oder Bildgrafiken via <code>lGraphic</code>) repräsentiert werden kann. <code>Caption</code> ermöglicht die optionale Betitelung und Querverweisbarkeit.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e2b0322fd03e2084", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung mathematischer Formeln (<code>MlFormula</code>) innerhalb des AUTOSAR-Metamodells (Generic Structure Template). Es spezifiziert die Struktur zur Einbettung, Formatierung und sprachspezifischen Auflösung von Formeldarstellungen in Dokumentationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>MlFormula</code> (spezialisiert <code>Paginateable</code>). Sie aggregiert per Komposition:</p>\n<ul class=\"fig-list\"><li><code>+formulaCaption</code> [0..1] auf <code>Caption</code> (spezialisiert <code>MultilanguageReferrable</code>)\n</li><li><code>+texMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+genericMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+verbatim</code> [0..1] auf <code>MultiLanguageVerbatim</code> (spezialisiert <code>Paginateable</code>, Attribute: <code>allowBreak :NameToken [0..1]</code>, <code>float :FloatEnum [0..1]</code>, <code>helpEntry :String [0..1]</code>, <code>pgwide :PgwideEnum [0..1]</code>)\n</li><li><code>+lGraphic</code> [0..*] auf <code>LGraphic</code> (spezialisiert <code>LanguageSpecific</code>)\n</li></ul>\n<p class=\"fig-p\">Die textuellen Formelcontainer verzweigen in sprachspezifische Ausprägungen:</p>\n<ul class=\"fig-list\"><li><code>MultiLanguagePlainText</code> aggregiert per Komposition über Rolle <code>+l10</code> [1..*] die Klasse <code>LPlainText</code> (spezialisiert <code>LanguageSpecific</code> und erbt von <code>MixedContentForPlainText</code>). <code>MixedContentForPlainText</code> ist als <code>WhitespaceControlled</code> und <code>«atpMixedString»</code> modelliert und besitzt keine Attribute.\n</li><li><code>MultiLanguageVerbatim</code> aggregiert per Komposition über Rolle <code>+l5</code> [1..*] die Klasse <code>LVerbatim</code> (spezialisiert <code>LanguageSpecific</code>, Stereotyp <code>«atpMixedString»</code>). <code>MixedContentForVerbatim</code> (spezialisiert <code>WhitespaceControlled</code>, Stereotyp <code>«atpMixedString»</code>) erbt von <code>LVerbatim</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Kompositionen definieren die hierarchische Schachtelung im AUTOSAR-XML-Dokumentenmodell (ARXML), wobei mehrsprachige Container (<code>MultiLanguage*</code>) zur Lokalisierung sprachspezifische Kindelemente bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen berücksichtigen, dass eine Formel über verschiedene mathematische Notationen (TeX via <code>texMath</code>, generische Textmathematik via <code>genericMath</code>, vorformatierter Text via <code>verbatim</code> oder Bildgrafiken via <code>lGraphic</code>) repräsentiert werden kann. <code>Caption</code> ermöglicht die optionale Betitelung und Querverweisbarkeit.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-92b0ac6de75f9c29", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung mathematischer Formeln (<code>MlFormula</code>) innerhalb des AUTOSAR-Metamodells (Generic Structure Template). Es spezifiziert die Struktur zur Einbettung, Formatierung und sprachspezifischen Auflösung von Formeldarstellungen in Dokumentationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>MlFormula</code> (spezialisiert <code>Paginateable</code>). Sie aggregiert per Komposition:</p>\n<ul class=\"fig-list\"><li><code>+formulaCaption</code> [0..1] auf <code>Caption</code> (spezialisiert <code>MultilanguageReferrable</code>)\n</li><li><code>+texMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+genericMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+verbatim</code> [0..1] auf <code>MultiLanguageVerbatim</code> (spezialisiert <code>Paginateable</code>, Attribute: <code>allowBreak :NameToken [0..1]</code>, <code>float :FloatEnum [0..1]</code>, <code>helpEntry :String [0..1]</code>, <code>pgwide :PgwideEnum [0..1]</code>)\n</li><li><code>+lGraphic</code> [0..*] auf <code>LGraphic</code> (spezialisiert <code>LanguageSpecific</code>)\n</li></ul>\n<p class=\"fig-p\">Die textuellen Formelcontainer verzweigen in sprachspezifische Ausprägungen:</p>\n<ul class=\"fig-list\"><li><code>MultiLanguagePlainText</code> aggregiert per Komposition über Rolle <code>+l10</code> [1..*] die Klasse <code>LPlainText</code> (spezialisiert <code>LanguageSpecific</code> und erbt von <code>MixedContentForPlainText</code>). <code>MixedContentForPlainText</code> ist als <code>WhitespaceControlled</code> und <code>«atpMixedString»</code> modelliert und besitzt keine Attribute.\n</li><li><code>MultiLanguageVerbatim</code> aggregiert per Komposition über Rolle <code>+l5</code> [1..*] die Klasse <code>LVerbatim</code> (spezialisiert <code>LanguageSpecific</code>, Stereotyp <code>«atpMixedString»</code>). <code>MixedContentForVerbatim</code> (spezialisiert <code>WhitespaceControlled</code>, Stereotyp <code>«atpMixedString»</code>) erbt von <code>LVerbatim</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Kompositionen definieren die hierarchische Schachtelung im AUTOSAR-XML-Dokumentenmodell (ARXML), wobei mehrsprachige Container (<code>MultiLanguage*</code>) zur Lokalisierung sprachspezifische Kindelemente bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen berücksichtigen, dass eine Formel über verschiedene mathematische Notationen (TeX via <code>texMath</code>, generische Textmathematik via <code>genericMath</code>, vorformatierter Text via <code>verbatim</code> oder Bildgrafiken via <code>lGraphic</code>) repräsentiert werden kann. <code>Caption</code> ermöglicht die optionale Betitelung und Querverweisbarkeit.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-35ad32cea868730d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung mathematischer Formeln (<code>MlFormula</code>) innerhalb des AUTOSAR-Metamodells (Generic Structure Template). Es spezifiziert die Struktur zur Einbettung, Formatierung und sprachspezifischen Auflösung von Formeldarstellungen in Dokumentationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>MlFormula</code> (spezialisiert <code>Paginateable</code>). Sie aggregiert per Komposition:</p>\n<ul class=\"fig-list\"><li><code>+formulaCaption</code> [0..1] auf <code>Caption</code> (spezialisiert <code>MultilanguageReferrable</code>). <code>Caption</code> aggregiert per Komposition <code>+desc</code> [0..1] auf <code>MultiLanguageOverviewParagraph</code>.\n</li><li><code>+texMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+genericMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+verbatim</code> [0..1] auf <code>MultiLanguageVerbatim</code> (spezialisiert <code>Paginateable</code>, Attribute: <code>allowBreak :NameToken [0..1]</code>, <code>float :FloatEnum [0..1]</code>, <code>helpEntry :String [0..1]</code>, <code>pgwide :PgwideEnum [0..1]</code>)\n</li><li><code>+lGraphic</code> [0..*] auf <code>LGraphic</code> (spezialisiert <code>LanguageSpecific</code>)\n</li></ul>\n<p class=\"fig-p\">Die textuellen Formelcontainer verzweigen in sprachspezifische Ausprägungen:</p>\n<ul class=\"fig-list\"><li><code>MultiLanguagePlainText</code> aggregiert per Komposition über Rolle <code>+l10</code> [1..*] die Klasse <code>LPlainText</code> (spezialisiert <code>LanguageSpecific</code> und erbt von <code>MixedContentForPlainText</code>). <code>MixedContentForPlainText</code> ist als <code>WhitespaceControlled</code> und <code>«atpMixedString»</code> modelliert.\n</li><li><code>MultiLanguageVerbatim</code> aggregiert per Komposition über Rolle <code>+l5</code> [1..*] die Klasse <code>LVerbatim</code> (spezialisiert <code>LanguageSpecific</code>, Stereotyp <code>«atpMixedString»</code>). <code>MixedContentForVerbatim</code> (spezialisiert <code>WhitespaceControlled</code>, Stereotyp <code>«atpMixedString»</code>) erbt von <code>LVerbatim</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Kompositionen definieren die hierarchische Schachtelung im AUTOSAR-XML-Dokumentenmodell (ARXML), wobei mehrsprachige Container (<code>MultiLanguage*</code>) zur Lokalisierung sprachspezifische Kindelemente bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen berücksichtigen, dass eine Formel über verschiedene mathematische Notationen (TeX via <code>texMath</code>, generische Textmathematik via <code>genericMath</code>, vorformatierter Text via <code>verbatim</code> oder Bildgrafiken via <code>lGraphic</code>) repräsentiert werden kann. <code>Caption</code> ermöglicht die optionale Betitelung, Querverweisbarkeit und Beschreibung (<code>desc</code> als <code>MultiLanguageOverviewParagraph</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ee536738f3a7f854", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung mathematischer Formeln (<code>MlFormula</code>) innerhalb des AUTOSAR-Metamodells (Generic Structure Template). Es spezifiziert die Struktur zur Einbettung, Formatierung und sprachspezifischen Auflösung von Formeldarstellungen in Dokumentationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>MlFormula</code> (spezialisiert <code>Paginateable</code>). Sie aggregiert per Komposition:</p>\n<ul class=\"fig-list\"><li><code>+formulaCaption</code> [0..1] auf <code>Caption</code> (spezialisiert <code>MultilanguageReferrable</code>). <code>Caption</code> aggregiert per Komposition <code>+desc</code> [0..1] auf <code>MultiLanguageOverviewParagraph</code>.\n</li><li><code>+texMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+genericMath</code> [0..1] auf <code>MultiLanguagePlainText</code>\n</li><li><code>+verbatim</code> [0..1] auf <code>MultiLanguageVerbatim</code> (spezialisiert <code>Paginateable</code>, Attribute: <code>allowBreak: NameToken [0..1]</code>, <code>float: FloatEnum [0..1]</code>, <code>helpEntry: String [0..1]</code>, <code>pgwide: PgwideEnum [0..1]</code>)\n</li><li><code>+lGraphic</code> [0..*] auf <code>LGraphic</code> (spezialisiert <code>LanguageSpecific</code>)\n</li></ul>\n<p class=\"fig-p\">Die textuellen Formelcontainer verzweigen in sprachspezifische Ausprägungen:</p>\n<ul class=\"fig-list\"><li><code>MultiLanguagePlainText</code> aggregiert per Komposition über Rolle <code>+l10</code> [1..*] die Klasse <code>LPlainText</code> (spezialisiert <code>LanguageSpecific</code> und erbt von <code>MixedContentForPlainText</code>). <code>MixedContentForPlainText</code> ist als <code>WhitespaceControlled</code> und <code>«atpMixedString»</code> modelliert.\n</li><li><code>MultiLanguageVerbatim</code> aggregiert per Komposition über Rolle <code>+l5</code> [1..*] die Klasse <code>LVerbatim</code> (spezialisiert <code>LanguageSpecific</code>, Stereotyp <code>«atpMixedString»</code>). <code>MixedContentForVerbatim</code> (spezialisiert <code>WhitespaceControlled</code>, Stereotyp <code>«atpMixedString»</code>) erbt von <code>LVerbatim</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Kompositionen definieren die hierarchische Schachtelung im AUTOSAR-XML-Dokumentenmodell (ARXML), wobei mehrsprachige Container (<code>MultiLanguage*</code>) zur Lokalisierung sprachspezifische Kindelemente bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierer und Generatoren müssen berücksichtigen, dass eine Formel über verschiedene mathematische Notationen (TeX via <code>texMath</code>, generische Textmathematik via <code>genericMath</code>, vorformatierter Text via <code>verbatim</code> oder Bildgrafiken via <code>lGraphic</code>) repräsentiert werden kann. <code>Caption</code> ermöglicht die optionale Betitelung, Querverweisbarkeit und Beschreibung (<code>desc</code> als <code>MultiLanguageOverviewParagraph</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5dda4457e5e710b4", "to": "FIG-e2b0322fd03e2084", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Klasse <code>MixedContentForPlainText</code> erhält den Stereotyp <code>«atpMixedString»</code>.\n</li><li>Das Attribut <code>+ contents: VerbatimString</code> in <code>MixedContentForPlainText</code> entfällt.\n</li><li>Redaktionell: Bei den Attributen von <code>MultiLanguageVerbatim</code> (<code>allowBreak</code>, <code>float</code>, <code>helpEntry</code>, <code>pgwide</code>) wurde ein Leerzeichen vor dem Doppelpunkt ergänzt (<code> :</code> statt <code>:</code>).\n</li></ul>"}, {"from": "FIG-e2b0322fd03e2084", "to": "FIG-92b0ac6de75f9c29", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-92b0ac6de75f9c29", "to": "FIG-35ad32cea868730d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Klasse <code>Caption</code> erhält eine gerichtete Komposition auf <code>MultiLanguageOverviewParagraph</code> mit der Rollenbezeichnung <code>+desc</code> und der Multiplizität <code>0..1</code>.\n</li></ul>"}, {"from": "FIG-35ad32cea868730d", "to": "FIG-ee536738f3a7f854", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bei den Attributen von <code>MultiLanguageVerbatim</code> (<code>allowBreak</code>, <code>float</code>, <code>helpEntry</code>, <code>pgwide</code>) wurde der Abstand vor dem Typ-Trennzeichen vereinheitlicht (Doppelpunkt direkt nach Attributname ohne vorangehendes Leerzeichen).\n</li></ul>"}]};
